// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp, address sender) public {
        vm.assume(blockNumber > 0);
        vm.assume(timestamp > 0);
        vm.assume(sender != address(0));
        vm.roll(blockNumber);
        vm.warp(timestamp);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        bool balanceZero = address(c).balance == 0;
        bool blockMultipleOf15 = (block.number % 15 == 0);
        assertTrue(balanceZero == blockMultipleOf15);
    }
}
